# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇİÇEKLİ BİTKİNİN KISIMLARI VE ÜREME ORGANLARI</text>\n  <rect x="30" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="132" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Koruyucu ve Destek Yapılar</text>\n  <text x="45" y="108" font-size="11.5" fill="#334155">• Çiçek Sapı: Çiçeği gövdeye bağlar.</text>\n  <text x="45" y="133" font-size="11.5" fill="#334155">• Çiçek Tablası: Kısımları taşır.</text>\n  <text x="45" y="158" font-size="11.5" fill="#334155">• Çanak Yaprak: Yeşildir, tomurcuk</text>\n  <text x="55" y="175" font-size="11" fill="#475569">halindeyken çiçeği korur, fotosentez yapar.</text>\n  <text x="45" y="200" font-size="11.5" fill="#334155">• Taç Yaprak: Renkli ve kokuludur,</text>\n  <text x="55" y="217" font-size="11" fill="#475569">böcekleri çekerek tozlaşmaya yardım eder.</text>\n  <rect x="250" y="55" width="200" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Erkek Organ (Stamen)</text>\n  <text x="350" y="115" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Başçık (Anter)</text>\n  <text x="350" y="135" text-anchor="middle" font-size="11.5" fill="#334155">Erkek üreme hücreleri olan</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11.5" fill="#334155">polenlerin (çiçek tozlarının)</text>\n  <text x="350" y="169" text-anchor="middle" font-size="11.5" fill="#334155">üretildiği kesecikli kısımdır.</text>\n  <text x="350" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. Sapçık (Filament)</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11.5" fill="#334155">Başçığı taşıyan ince uzantıdır.</text>\n  <rect x="465" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="567" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dişi Organ (Pistil)</text>\n  <text x="480" y="110" font-size="11.5" fill="#334155">• Dişicik Tepesi: Polenlerin</text>\n  <text x="490" y="127" font-size="11" fill="#475569">tutunduğu nemli ve yapışkan uçtur.</text>\n  <text x="480" y="152" font-size="11.5" fill="#334155">• Dişicik Borusu: Poleni</text>\n  <text x="490" y="169" font-size="11" fill="#475569">yumurtalığa ileten kanaldır.</text>\n  <text x="480" y="194" font-size="11.5" font-weight="bold" fill="#854d0e">• Yumurtalık: Tohum taslağı ve</text>\n  <text x="490" y="211" font-size="11" fill="#854d0e">dişi üreme hücresi (yumurta) buradadır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇİÇEKLİ BİTKİLERDE HAYAT DÖNGÜSÜ: TOZLAŞMADAN MEYVEYE</text>\n  <rect x="25" y="65" width="145" height="155" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="97" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Tozlaşma</text>\n  <text x="97" y="118" text-anchor="middle" font-size="11" fill="#334155">Başçıktaki polenlerin</text>\n  <text x="97" y="136" text-anchor="middle" font-size="11" fill="#334155">rüzgâr, su, böcek ve</text>\n  <text x="97" y="154" text-anchor="middle" font-size="11" fill="#334155">kuşlarla dişicik</text>\n  <text x="97" y="172" text-anchor="middle" font-size="11" fill="#334155">tepesine taşınmasıdır.</text>\n  <rect x="195" y="65" width="145" height="155" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="267" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Döllenme</text>\n  <text x="267" y="118" text-anchor="middle" font-size="11" fill="#334155">Yumurtalıkta sperm</text>\n  <text x="267" y="136" text-anchor="middle" font-size="11" fill="#334155">ve yumurta çekirdeği</text>\n  <text x="267" y="154" text-anchor="middle" font-size="11" fill="#334155">birleşerek zigotu ve</text>\n  <text x="267" y="172" text-anchor="middle" font-size="11" fill="#334155">embriyoyu oluşturur.</text>\n  <rect x="365" y="65" width="145" height="155" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="437" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Tohum Oluşumu</text>\n  <text x="437" y="118" text-anchor="middle" font-size="11" fill="#334155">Tohum taslağı gelişip</text>\n  <text x="437" y="136" text-anchor="middle" font-size="11" fill="#334155">içinde embriyo ve</text>\n  <text x="437" y="154" text-anchor="middle" font-size="11" fill="#334155">çenek (besin dokusu)</text>\n  <text x="437" y="172" text-anchor="middle" font-size="11" fill="#334155">bulunan tohuma dönüşür.</text>\n  <rect x="535" y="65" width="145" height="155" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="607" y="92" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">4. Meyve Oluşumu</text>\n  <text x="607" y="118" text-anchor="middle" font-size="11" fill="#334155">Yumurtalık etlenip</text>\n  <text x="607" y="136" text-anchor="middle" font-size="11" fill="#334155">gelişerek tohumu</text>\n  <text x="607" y="154" text-anchor="middle" font-size="11" fill="#334155">koruyan ve yayan</text>\n  <text x="607" y="172" text-anchor="middle" font-size="11" fill="#334155">meyveyi meydana getirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TOHUMUN ÇİMLENME ŞARTLARI (SOS KURALI)</text>\n  <rect x="40" y="55" width="300" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="190" y="80" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">Çimlenme İçin Zorunlu (SOS)</text>\n  <text x="60" y="112" font-size="12" font-weight="bold" fill="#166534">1. Su (Nem):</text>\n  <text x="145" y="112" font-size="11.5" fill="#334155">Tohum kabuğunu çatlatır, enzimleri çalıştırır.</text>\n  <text x="60" y="145" font-size="12" font-weight="bold" fill="#166534">2. Oksijen (Hava):</text>\n  <text x="175" y="145" font-size="11.5" fill="#334155">Embriyonun solunumu için şarttır.</text>\n  <text x="60" y="178" font-size="12" font-weight="bold" fill="#166534">3. Uygun Sıcaklık:</text>\n  <text x="175" y="178" font-size="11.5" fill="#334155">Canlılık olaylarının hızını belirler.</text>\n  <text x="190" y="212" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Besin kaynağı: Tohumdaki Çenek!</text>\n  <rect x="360" y="55" width="300" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="510" y="80" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#a16207">Çimlenmede Gerekli Olmayanlar</text>\n  <text x="380" y="112" font-size="11.5" fill="#334155">• Güneş Işığı: Henüz yeşil yaprak</text>\n  <text x="395" y="130" font-size="11" fill="#475569">olmadığından fotosentez yapılmaz.</text>\n  <text x="380" y="158" font-size="11.5" fill="#334155">• Toprak: Pamuk arasında da çimlenir.</text>\n  <text x="380" y="185" font-size="11.5" fill="#334155">• Karbondioksit: İlk yapraklar çıkıp</text>\n  <text x="395" y="203" font-size="11" fill="#475569">büyüme başlayınca fotosentez için gerekir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
